// Initialize state and assign random models for this run.
const row = $json;
const modelPool = Array.isArray(row.model_pool) ? row.model_pool : JSON.parse(row.model_pool);
const agentRoles = Array.isArray(row.agent_roles) ? row.agent_roles : JSON.parse(row.agent_roles);
const weights = typeof row.weights === 'object' ? row.weights : JSON.parse(row.weights);

function pickRandomModel() {
  return modelPool[Math.floor(Math.random() * modelPool.length)];
}

const agentModelAssignments = agentRoles.map((role, i) => ({
  agent_id: i + 1,
  role,
  model: pickRandomModel(),
}));

const phaseModels = {
  generation: pickRandomModel(),
  evaluation: pickRandomModel(),
  objections: pickRandomModel(),
  optimization: pickRandomModel(),
};

return [{
  json: {
    ...row,
    model_pool: modelPool,
    agent_roles: agentRoles,
    weights,
    agent_model_assignments: agentModelAssignments,
    phase_models: phaseModels,
    state: {
      iteration: 1,
      max_iterations: Number(row.max_iterations || 5),
      stop_threshold: Number(row.stop_threshold || 8.5),
      ads: [],
      top_ads: [],
      logs: [],
      winner: null,
      stop: false
    }
  }
}];

