// Aggregate 20-agent scoring, rank ads, keep top 3, and check stop conditions.
const root = $('Store Initial Ads').first().json;
const content = $json.choices?.[0]?.message?.content || '{}';
let parsed;
try {
  parsed = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  parsed = { ad_reviews: [] };
}

const adReviews = Array.isArray(parsed.ad_reviews) ? parsed.ad_reviews : [];
const adsById = new Map((root.state.ads || []).map(a => [a.ad_id, a]));
const w = root.weights;

function avg(arr, key) {
  if (!arr.length) return 0;
  return arr.reduce((s, x) => s + Number(x[key] || 0), 0) / arr.length;
}

const scored = adReviews.map(item => {
  const reviews = Array.isArray(item.agent_reviews) ? item.agent_reviews : [];
  const avg_ctr_score = avg(reviews, 'ctr_score');
  const avg_cpl_score = avg(reviews, 'cpl_score');
  const avg_lead_quality_score = avg(reviews, 'lead_quality_score');
  const avg_realism_score = avg(reviews, 'realism_score');
  const final_score = (avg_ctr_score * w.ctr) + (avg_cpl_score * w.cpl) + (avg_lead_quality_score * w.lead_quality) + (avg_realism_score * w.realism);

  const strengths = reviews.map(r => r.biggest_strength).filter(Boolean);
  const weaknesses = reviews.map(r => r.biggest_weakness).filter(Boolean);
  const improvements = reviews.map(r => r.suggested_improvement).filter(Boolean);

  return {
    ...(adsById.get(item.ad_id) || { ad_id: item.ad_id }),
    agent_reviews: reviews,
    avg_ctr_score: Number(avg_ctr_score.toFixed(3)),
    avg_cpl_score: Number(avg_cpl_score.toFixed(3)),
    avg_lead_quality_score: Number(avg_lead_quality_score.toFixed(3)),
    avg_realism_score: Number(avg_realism_score.toFixed(3)),
    final_score: Number(final_score.toFixed(3)),
    biggest_strength: strengths[0] || '',
    biggest_weakness: weaknesses[0] || '',
    suggested_improvements: improvements
  };
});

scored.sort((a, b) => b.final_score - a.final_score);
const topAds = scored.slice(0, 3);
const best = scored[0] || null;

const priorLogs = root.state.logs || [];
const now = new Date().toISOString();
const iteration = root.state.iteration;

const logRows = scored.map(ad => ({
  timestamp: now,
  ad_idea: root.ad_idea,
  iteration,
  ad_id: ad.ad_id,
  parent_ad_id: ad.parent_ad_id || '',
  headline: ad.headline,
  primary_text: ad.primary_text,
  cta: ad.cta,
  creative_concept: ad.creative_concept,
  image_prompt: ad.image_prompt,
  video_prompt: ad.video_prompt,
  hook_overlay_text: ad.hook_overlay_text,
  thumbnail_text: ad.thumbnail_text,
  avg_ctr_score: ad.avg_ctr_score,
  avg_cpl_score: ad.avg_cpl_score,
  avg_lead_quality_score: ad.avg_lead_quality_score,
  avg_realism_score: ad.avg_realism_score,
  final_score: ad.final_score,
  top_objections: '',
  biggest_strength: ad.biggest_strength || '',
  biggest_weakness: ad.biggest_weakness || '',
  winning_ad_flag: best && best.ad_id === ad.ad_id ? 'yes' : 'no'
}));

const stop = !!(best && best.final_score >= Number(root.state.stop_threshold));

return [{
  json: {
    ...root,
    state: {
      ...root.state,
      ads: scored,
      top_ads: topAds,
      winner: stop ? { ...best, winning_iteration: iteration } : (root.state.winner || null),
      stop,
      logs: [...priorLogs, ...logRows]
    },
    sheet_rows: logRows
  }
}];

