// Merge objection reports and optimized ads into next iteration state.
const root = $('Score + Rank + Top 3').first().json;
const objectionContent = $('Simulate Comments + Objections').first().json.choices?.[0]?.message?.content || '{}';
let objectionParsed;
try {
  objectionParsed = typeof objectionContent === 'string' ? JSON.parse(objectionContent) : objectionContent;
} catch (e) {
  objectionParsed = { objection_reports: [] };
}

const optimizeContent = $json.choices?.[0]?.message?.content || '{}';
let optimizedParsed;
try {
  optimizedParsed = typeof optimizeContent === 'string' ? JSON.parse(optimizeContent) : optimizeContent;
} catch (e) {
  optimizedParsed = { optimized_ads: [] };
}

const objectionReports = Array.isArray(objectionParsed.objection_reports) ? objectionParsed.objection_reports : [];
const optimizedAds = Array.isArray(optimizedParsed.optimized_ads) ? optimizedParsed.optimized_ads : [];

const nextIteration = root.state.iteration + 1;
const stopForMaxIterations = nextIteration > Number(root.state.max_iterations);

// On next round, only top 3 refined creatives continue.
const nextAds = optimizedAds.map((ad, idx) => ({
  ad_id: ad.ad_id || `ITER${nextIteration}_A${idx + 1}`,
  parent_ad_id: ad.parent_ad_id || root.state.top_ads[idx]?.ad_id || null,
  headline: ad.headline || '',
  primary_text: ad.primary_text || '',
  cta: ad.cta || '',
  creative_concept: ad.creative_concept || '',
  image_prompt: ad.image_prompt || '',
  video_prompt: ad.video_prompt || '',
  hook_overlay_text: ad.hook_overlay_text || '',
  thumbnail_text: ad.thumbnail_text || '',
  top_objections_addressed: ad.top_objections_addressed || [],
  why_improved: ad.why_improved || ''
}));

const priorWinner = root.state.winner;
const winner = priorWinner || (root.state.ads?.[0] ? { ...root.state.ads[0], winning_iteration: root.state.iteration } : null);

return [{
  json: {
    ...root,
    objection_reports: objectionReports,
    state: {
      ...root.state,
      iteration: nextIteration,
      ads: nextAds,
      top_ads: nextAds,
      stop: stopForMaxIterations,
      winner
    }
  }
}];

// Final payload containing winning ad + full creative pack.
const root = $json;
const winner = root.state.winner || root.state.ads?.[0] || null;
const finalists = (root.state.ads || []).slice(0, 3);

const final = {
  winning_ad: winner?.ad_id || null,
  winning_score: winner?.final_score || null,
  winning_iteration: winner?.winning_iteration || root.state.iteration,
  headline: winner?.headline || '',
  primary_text: winner?.primary_text || '',
  cta: winner?.cta || '',
  creative_concept: winner?.creative_concept || '',
  image_prompt: winner?.image_prompt || '',
  video_prompt: winner?.video_prompt || '',
  hook_overlay_text: winner?.hook_overlay_text || '',
  thumbnail_text: winner?.thumbnail_text || '',
  summary_of_why_it_won: winner?.why_improved || 'Highest weighted score across CTR, CPL efficiency proxy, lead quality, and realism.',
  top_objections_addressed: winner?.top_objections_addressed || [],
  all_top_3_finalists: finalists
};

return [{ json: { ...root, final_output: final } }];
